package com.aoo.bcg.wordcard;
import java.util.List;import java.util.Map;import java.util.Set;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
final class WordCardCoreEngineTest {
    private static final WordCardRuleSet<WordCardRuleContext> RULES=new WordCardRuleSet<>(){public Set<WordCardOperation> allowedOperations(int s,WordCardRuleContext c){return Set.of(WordCardOperation.values());}public boolean canWin(int s,List<Integer>c,int i,WordCardRuleContext x){return x.huXi()>=15;}};
    @Test void runsAuthoritativeDrawDiscardWeiAndHu(){var initial=new WordCardState(Map.of(0,List.of(1,1),1,List.of(2,2)),List.of(3),List.of(),Map.of(0,0,1,0),0,WordCardPhase.PLAYING,null,null);var engine=new WordCardCoreEngine<>(RULES);var drawn=engine.apply(initial,WordCardCommand.of(WordCardOperation.DRAW,0),new WordCardRuleContext(0,0));var discarded=engine.apply(drawn,WordCardCommand.of(WordCardOperation.DISCARD,0,3),new WordCardRuleContext(0,0));var wei=engine.apply(discarded,WordCardCommand.of(WordCardOperation.WEI,1,2),new WordCardRuleContext(0,0));var won=engine.apply(wei,WordCardCommand.of(WordCardOperation.HU,1),new WordCardRuleContext(15,0));assertEquals(List.of(3),initial.deck());assertEquals(3,wei.huXi().get(1));assertEquals(WordCardPhase.FINISHED,won.phase());}
    @Test void rejectsWrongTurnAndFalseHu(){var state=new WordCardState(Map.of(0,List.of(1),1,List.of(2)),List.of(3),List.of(),Map.of(),0,WordCardPhase.PLAYING,null,null);var engine=new WordCardCoreEngine<>(RULES);assertThrows(IllegalStateException.class,()->engine.apply(state,WordCardCommand.of(WordCardOperation.DRAW,1),new WordCardRuleContext(0,0)));assertThrows(IllegalStateException.class,()->engine.apply(state,WordCardCommand.of(WordCardOperation.HU,0),new WordCardRuleContext(14,0)));}
    @Test void resolvesResponsePriorityAndEvaluatesRegionalCombinationComponents(){var response=WordCardResponseResolver.resolve(List.of(new WordCardResponseResolver.Response(1,WordCardOperation.PAO),new WordCardResponseResolver.Response(2,WordCardOperation.HU)),0,3);assertEquals(2,response.seatId());var combinations=BuiltinMingTangRules.evaluate(new MingTangContext(0,10,0,3,1));assertTrue(combinations.containsAll(Set.of(MingTang.BLACK_HU,MingTang.ALL_BIG,MingTang.KAN,MingTang.TI_LONG)));}
}
